#!/bin/sh
# Write or check tests/main.rs, the one integration-test binary of each crate (the organization's
# rule "Tests stay fast": one integration-test binary per crate; story
# one-integration-test-binary-per-crate).
# Usage: sh taskfiles/test-main.sh write | check
#
# The crates are the directories under GATE_CRATES (default crates) that hold a Cargo.toml. A crate
# has tests when its tests/ directory holds a file *.rs. For each such crate tests/main.rs is
# generated from the directory: the line "// Generated by taskfiles/test-main.sh (task test-main)
# from the files of this directory; do not edit it.", then "mod <name>;" for every tests/<name>.rs
# but main.rs, and for support where tests/support/mod.rs exists, in byte order (LC_ALL=C sort).
# The crate root resolves "mod <name>;" to tests/<name>.rs; a file reaches the shared helpers with
# "use crate::support;".
#
# A package named in TEST_MAIN_SELECT (default "swell", names separated by blanks; "" names none)
# lets one build compile a part of its modules: before each "mod <name>;" but support its
# tests/main.rs has the line "#[cfg(any(not(test_modules), test_modules = "<name>"))]". The
# package declares the cfg in its manifest, [lints.rust] unexpected_cfgs with check-cfg
# "cfg(test_modules, values(any()))" (crates/swell/Cargo.toml), so the lint unexpected_cfgs stays
# on for every other name: a misspelled feature or cfg name in a test module fails a build with
# -D warnings (tests/gate/build-refuses-a-misspelled-feature-in-a-test-module.sh). A build
# without the cfg test_modules (every build of the gate) compiles every module, as before; a
# build that passes rustc "--cfg test_modules" and "--cfg test_modules=\"<name>\"" for some
# names (the bare name too: cfg(test_modules) does not hold for a name set only with a value),
# which only "cargo rustc ... --test main -- <args>" passes to the test target alone and not to
# the library, compiles those modules and support (taskfiles/stack-profiles.yml, STACK_MODULES).
#
# write: writes tests/main.rs of every crate with tests where it differs from the generated text,
#   and prints "test-main: wrote <file>" for each, then "test-main: <n> crate(s) with tests, <w>
#   tests/main.rs written".
# check: generates the same in memory, builds nothing, and fails, naming the file, on
#   - a tests/main.rs that differs from the generated one, or is missing ("test-main: <file>
#     differs from its generation; run sh taskfiles/test-main.sh write", then the difference);
#   - a crate with tests whose [package] lacks "autotests = false" ("test-main: <manifest>:
#     [package] lacks autotests = false; a file under tests/ would be a test binary of its own");
#   - a crate with tests that lacks exactly one [[test]] named main ("test-main: <manifest>: <n>
#     [[test]] section(s), <m> named main; one [[test]] with name = "main" and path =
#     "tests/main.rs"");
#   - a module named lib, doc, or as a binary target of the package with "-" written "_"
#     ("test-main: <file>: a module named <name>, which the test list writes for <what>"): the
#     test list (taskfiles/host-requirements.yml) writes a test of the binary main as
#     <package>::<module>::<test>, and these names are those of the library's unit tests, the doc
#     tests and a binary's unit tests.
#   It fails too when GATE_CRATES holds no crate with tests (a check that reads nothing fails).
#   Passing, it prints "test-main: <n> crate(s) with tests, each with one integration-test binary
#   and its tests/main.rs as generated".
# The planted script tests/gate/test-binaries-check-refuses-a-main-rs-that-is-not-generated.sh
# holds it; the task test-binaries-check (taskfiles/test-binaries.yml) runs the check first.

mode=${1:-}
case "$mode" in
  write | check) ;;
  *) echo "test-main: usage: sh taskfiles/test-main.sh write | check"; exit 2 ;;
esac
crates=${GATE_CRATES:-crates}
select=${TEST_MAIN_SELECT-swell}
header='// Generated by taskfiles/test-main.sh (task test-main) from the files of this directory; do not edit it.'
export LC_ALL=C

# The module names of the crate $1, one per line, in byte order.
modules() {
  {
    for file in "$1"/tests/*.rs; do
      [ -f "$file" ] || continue
      name=${file##*/}
      name=${name%.rs}
      [ "$name" = main ] && continue
      printf '%s\n' "$name"
    done
    if [ -f "$1/tests/support/mod.rs" ]; then echo support; fi
  } | sort -u
}

# Whether the package of the crate $1 is named in TEST_MAIN_SELECT.
selectable() {
  package=$(awk -F '"' '/^\[/ { section = $0 } section == "[package]" && /^name *=/ { print $2; exit }' "$1/Cargo.toml")
  for name in $select; do
    [ "$name" = "$package" ] && return 0
  done
  return 1
}

# The text of tests/main.rs of the crate $1.
generate() {
  printf '%s\n' "$header"
  if selectable "$1"; then
    modules "$1" | awk '
      $0 != "support" { printf "#[cfg(any(not(test_modules), test_modules = \"%s\"))]\n", $0 }
      { printf "mod %s;\n", $0 }
    '
  else
    modules "$1" | sed 's/^\(.*\)$/mod \1;/'
  fi
}

# Whether the crate $1 has tests: a file *.rs in tests/.
has_tests() {
  for file in "$1"/tests/*.rs; do
    [ -f "$file" ] && return 0
  done
  return 1
}

# The names of the binary targets of the crate $1 with "-" written "_", one per line: the package
# for src/main.rs, src/bin/<name>.rs and src/bin/<name>/main.rs, and every [[bin]] name.
binaries() {
  manifest=$1/Cargo.toml
  {
    if [ -f "$1/src/main.rs" ]; then
      awk -F '"' '/^\[/ { section = $0 } section == "[package]" && /^name *=/ { print $2; exit }' "$manifest"
    fi
    for file in "$1"/src/bin/*.rs "$1"/src/bin/*/main.rs; do
      [ -f "$file" ] || continue
      case "$file" in
        */main.rs) name=${file%/main.rs}; name=${name##*/} ;;
        *) name=${file##*/}; name=${name%.rs} ;;
      esac
      printf '%s\n' "$name"
    done
    awk -F '"' '/^\[/ { section = $0 } section == "[[bin]]" && /^name *=/ { print $2 }' "$manifest"
  } | sed 's/-/_/g' | sort -u
}

found=0
crates_seen=0
written=0
bad=0
for dir in "$crates"/*/; do
  dir=${dir%/}
  [ -f "$dir/Cargo.toml" ] || continue
  crates_seen=$((crates_seen + 1))
  has_tests "$dir" || continue
  found=$((found + 1))
  main=$dir/tests/main.rs
  manifest=$dir/Cargo.toml
  if [ "$mode" = write ]; then
    if [ ! -f "$main" ] || ! generate "$dir" | cmp -s "$main" -; then
      generate "$dir" > "$main" || { echo "test-main: cannot write $main"; exit 1; }
      echo "test-main: wrote $main"
      written=$((written + 1))
    fi
    continue
  fi
  if [ ! -f "$main" ]; then
    echo "test-main: $main is missing; run sh taskfiles/test-main.sh write"
    bad=$((bad + 1))
  elif ! generate "$dir" | cmp -s "$main" -; then
    echo "test-main: $main differs from its generation; run sh taskfiles/test-main.sh write"
    generate "$dir" | diff "$main" - | sed -n '1,20s/^/  /p'
    bad=$((bad + 1))
  fi
  if ! awk '
    /^[ \t]*\[/ { section = $0; gsub(/[ \t]/, "", section) }
    section == "[package]" && /^[ \t]*autotests[ \t]*=[ \t]*false[ \t]*(#.*)?$/ { found = 1 }
    END { exit !found }
  ' "$manifest"; then
    echo "test-main: $manifest: [package] lacks autotests = false; a file under tests/ would be a test binary of its own"
    bad=$((bad + 1))
  fi
  counts=$(awk '
    /^[ \t]*\[/ { section = $0; gsub(/[ \t]/, "", section); if (section == "[[test]]") tests++ }
    section == "[[test]]" && /^[ \t]*name[ \t]*=[ \t]*"main"[ \t]*(#.*)?$/ { main++ }
    END { print tests + 0, main + 0 }
  ' "$manifest")
  if [ "$counts" != "1 1" ]; then
    echo "test-main: $manifest: ${counts% *} [[test]] section(s), ${counts#* } named main; one [[test]] with name = \"main\" and path = \"tests/main.rs\""
    bad=$((bad + 1))
  fi
  bins=$(binaries "$dir")
  for name in $(modules "$dir"); do
    what=""
    case "$name" in
      lib) what="the unit tests of the library" ;;
      doc) what="the doc tests" ;;
      *) if printf '%s\n' "$bins" | grep -qxF "$name"; then what="the unit tests of the binary target $name"; fi ;;
    esac
    if [ -n "$what" ]; then
      echo "test-main: $dir/tests/$name.rs: a module named $name, which the test list writes for $what"
      bad=$((bad + 1))
    fi
  done
done

if [ "$crates_seen" -eq 0 ]; then
  echo "test-main: no crate (a directory with a Cargo.toml) under $crates"
  exit 1
fi
if [ "$found" -eq 0 ]; then
  echo "test-main: no crate under $crates has a file *.rs in tests/"
  exit 1
fi
if [ "$mode" = write ]; then
  echo "test-main: $found crate(s) with tests, $written tests/main.rs written"
  exit 0
fi
if [ "$bad" -gt 0 ]; then
  echo "test-main: $bad problem(s) in the test layout of $found crate(s) with tests under $crates"
  exit 1
fi
echo "test-main: $found crate(s) with tests, each with one integration-test binary and its tests/main.rs as generated"
